INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('全国总工会部署开展2025年工会送清凉工作', NULL, '2025-07-01 00:00:00', '', 0, '全国总工会印发通知部署2025年工会送清凉活动，安排近4000万元资金，聚焦快递员、外卖配送员、网约车司机、货车司机等新就业形态劳动者，依托工会驿站等阵地提供避暑场所和清凉物资。', 'PUBLISHED', 'EXTERNAL', 'https://www.workercn.cn/papers/grrb/2025/07/04/1/news-5.html', NULL, '中华全国总工会', '健康关爱', '全国总工会印发通知部署2025年工会送清凉活动，安排近4000万元资金，聚焦快递员、外卖配送员、网约车司机、货车司机等新就业形态劳动者，依托工会驿站等阵地提供避暑场所和清凉物资。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('关爱新就业群体，送清凉活动部署开展', NULL, '2025-07-07 00:00:00', '', 0, '中国社会工作报报道全国总工会部署工会送清凉活动，聚焦夏季露天作业人员及快递员、网约配送员、网约车司机、货车司机等新就业形态劳动者，通过工会驿站提供避暑场所、清凉包及暑期防病知识宣传。', 'PUBLISHED', 'EXTERNAL', 'https://www.zyshgzb.gov.cn/n1/2025/0707/c460717-40516236.html', NULL, '中共中央社会工作部（中国社会工作报）', '健康关爱', '中国社会工作报报道全国总工会部署工会送清凉活动，聚焦夏季露天作业人员及快递员、网约配送员、网约车司机、货车司机等新就业形态劳动者，通过工会驿站提供避暑场所、清凉包及暑期防病知识宣传。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('王作：全国总工会已服务近7万名新就业形态劳动者子女', NULL, '2025-12-01 00:00:00', '', 0, '全国总工会权益保障部新兴领域工作指导处处长王作在“新业态·共聚力·益童行”2025新就业群体子女关爱行动研讨会致辞中介绍，“十四五”期间各级工会累计服务近7万名新就业形态劳动者子女，通过工会夏令营、爱心托管班、“金秋助学”“求学圆梦”等构建关爱服务体系。', 'PUBLISHED', 'EXTERNAL', 'http://gongyishibao.com/html/renwuguandian/2025/12/32266.html', NULL, '全国总工会权益保障部（“新业态·共聚力·益童行”2025新就业群体子女关爱行动研讨会）', '子女关爱', '全国总工会权益保障部新兴领域工作指导处处长王作在“新业态·共聚力·益童行”2025新就业群体子女关爱行动研讨会致辞中介绍，“十四五”期间各级工会累计服务近7万名新就业形态劳动者子女，通过工会夏令营、爱心托管班、“金秋助学”“求学圆梦”等构建关爱服务体系。', 'MEDIA');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('北京市总工会开展网约车司机夏季关爱行动', NULL, '2025-07-29 00:00:00', '北京市大兴国际机场高速路礼贤服务区工会驿站', 0, '“一城清爽·会新一夏”北京市总工会网约车司机夏季关爱行动在礼贤服务区工会驿站举行，为网约车司机提供免费理发、健康体检、职工互助保障、心理关爱等服务并现场办理工会会员互助服务卡。', 'PUBLISHED', 'EXTERNAL', 'https://www.workercn.cn/c/2025-07-29/8570696.shtml', '110100', '北京市总工会、北京市交通运输工会', '健康关爱', '“一城清爽·会新一夏”北京市总工会网约车司机夏季关爱行动在礼贤服务区工会驿站举行，为网约车司机提供免费理发、健康体检、职工互助保障、心理关爱等服务并现场办理工会会员互助服务卡。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('北京为骑手开设技能与权益课堂', NULL, '2025-11-03 00:00:00', '北京市东城区簋街；北京市怀柔区', 0, '东城区人社局联合北新桥街道在簋街试点推出“骑心守护微课堂”，把新就业群体权益保障政策宣讲嵌入骑手早会；怀柔区通过“小哥夜校”“日间小哥学堂”免费提供电工、咖啡师、短视频制作等9类技能培训。', 'PUBLISHED', 'EXTERNAL', 'http://news.cyol.com/gb/articles/2025-11/03/content_wd2xqNuRVK.html', '110100', '北京市东城区人力资源和社会保障局、北新桥街道；北京市怀柔区人力资源和社会保障局', '技能培训', '东城区人社局联合北新桥街道在簋街试点推出“骑心守护微课堂”，把新就业群体权益保障政策宣讲嵌入骑手早会；怀柔区通过“小哥夜校”“日间小哥学堂”免费提供电工、咖啡师、短视频制作等9类技能培训。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('2025年北京工会夏令营开营', NULL, '2025-07-17 00:00:00', '北京工人体育场', 0, '北京市总工会主办的2025年北京工会夏令营开营，作为全国总工会工会夏令营活动之一，重点面向新就业形态劳动者等5类群体10至15岁子女，千名小营员开展为期4天的参观研学与实践活动。', 'PUBLISHED', 'EXTERNAL', 'https://www.workercn.cn/c/2025-07-23/8567582.shtml', '110100', '北京市总工会', '子女关爱', '北京市总工会主办的2025年北京工会夏令营开营，作为全国总工会工会夏令营活动之一，重点面向新就业形态劳动者等5类群体10至15岁子女，千名小营员开展为期4天的参观研学与实践活动。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('本市首个新就业群体法律援助公益项目“城市蜂鸟”推出 三部门发布14项举措保障新就业群体权益', NULL, '2025-06-03 00:00:00', '北京市', 0, '北京市司法局联合市市场监管局、市总工会发布14项举措维护新就业群体合法权益，并推出全市首个新就业群体法律援助公益项目“城市蜂鸟”，为网约配送人员提供公益法律服务。', 'PUBLISHED', 'EXTERNAL', 'https://www.beijing.gov.cn/ywdt/gzdt/202506/t20250604_4105198.html', '110100', '北京市司法局、北京市市场监管局、北京市总工会', '法律援助', '北京市司法局联合市市场监管局、市总工会发布14项举措维护新就业群体合法权益，并推出全市首个新就业群体法律援助公益项目“城市蜂鸟”，为网约配送人员提供公益法律服务。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('移动体检车+固定场地 通州千名新就业形态劳动者享受免费体检', NULL, '2025-08-21 00:00:00', '北京市通州区潞城建设开发有限公司、台湖镇党群服务中心', 0, '通州区总工会采取“移动体检车+固定场地”模式，为快递、外卖、网约车等行业一千余名新就业形态劳动者提供免费体检，项目涵盖血常规、心理测评、内科等十多个项目并建立健康档案。', 'PUBLISHED', 'EXTERNAL', 'https://www.beijing.gov.cn/ywdt/gqrd/202508/t20250821_4180144.html', '110100', '北京市通州区总工会', '健康关爱', '通州区总工会采取“移动体检车+固定场地”模式，为快递、外卖、网约车等行业一千余名新就业形态劳动者提供免费体检，项目涵盖血常规、心理测评、内科等十多个项目并建立健康档案。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('北京市总工会慰问一线劳动者', NULL, '2025-05-01 00:00:00', '北京市总工会职工服务中心门前广场', 0, '北京市总工会领导带队慰问新就业形态劳动者等一线劳动者，现场由北京康复医院医护人员为快递员、外卖配送员提供免费健康体检，并针对腰椎间盘突出、颈椎病等常见职业病提供一对一健康咨询。', 'PUBLISHED', 'EXTERNAL', 'https://www.workercn.cn/c/2025-05-03/8513960.shtml', '110100', '北京市总工会、北京康复医院', '健康关爱', '北京市总工会领导带队慰问新就业形态劳动者等一线劳动者，现场由北京康复医院医护人员为快递员、外卖配送员提供免费健康体检，并针对腰椎间盘突出、颈椎病等常见职业病提供一对一健康咨询。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('上海工会启动“夏送清凉”活动 覆盖百家驿站惠及近50万户外劳动者', NULL, '2025-08-01 00:00:00', '上海市徐汇区滨江党群服务中心站点（覆盖全市100家最美工会驿站）', 0, '“工会送清凉 冰爽‘驿’站通”2025“夏送清凉”启动仪式在徐汇区滨江党群服务中心站点举行，活动覆盖全市100家最美工会驿站并配备百个爱心冰柜，累计送出50万份清凉饮品，预计惠及近50万名户外劳动者。', 'PUBLISHED', 'EXTERNAL', 'https://www.workercn.cn/c/2025-08-02/8573592.shtml', '310100', '上海市总工会、上海市总工会职工服务中心、上海市职工帮困基金会、徐汇区总工会', '健康关爱', '“工会送清凉 冰爽‘驿’站通”2025“夏送清凉”启动仪式在徐汇区滨江党群服务中心站点举行，活动覆盖全市100家最美工会驿站并配备百个爱心冰柜，累计送出50万份清凉饮品，预计惠及近50万名户外劳动者。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('【蹲点日记】移动体检车“首航”', NULL, '2025-06-27 00:00:00', '上海市沪东工人文化宫', 0, '全国总工会赠送的编号“17”移动体检车在上海市沪东工人文化宫开展面向京东达达新就业形态劳动者的专场移动体检活动，43名达达快递员完成扫码核销、基础检查与专项检查。', 'PUBLISHED', 'EXTERNAL', 'https://www.workercn.cn/papers/grrb/2025/07/09/2/news-5.html', '310100', '全国总工会达达蹲点组、上海市总工会、杨浦区总工会', '健康关爱', '全国总工会赠送的编号“17”移动体检车在上海市沪东工人文化宫开展面向京东达达新就业形态劳动者的专场移动体检活动，43名达达快递员完成扫码核销、基础检查与专项检查。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('上海市总工会2024年实事项目“新就业形态劳动者暖心行动”启动', NULL, '2024-04-24 00:00:00', '上海市青浦区申通快递（“橙BA”比赛现场）', 0, '上海市总工会2024年实事项目“新就业形态劳动者暖心行动”启动，推出暖心体检护身心、暖心互助抗风险等八项服务举措，启动仪式上向申通快递小哥发放劳动保障呵护礼包、健康服务关爱礼包及微心愿实物礼包。', 'PUBLISHED', 'EXTERNAL', 'https://www.workercn.cn/c/2024-04-25/8234183.shtml', '310100', '上海市总工会、青浦区总工会、重固镇总工会', '权益保障', '上海市总工会2024年实事项目“新就业形态劳动者暖心行动”启动，推出暖心体检护身心、暖心互助抗风险等八项服务举措，启动仪式上向申通快递小哥发放劳动保障呵护礼包、健康服务关爱礼包及微心愿实物礼包。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('上海市总工会派送“会了嘛”法治外卖', NULL, '2025-04-16 00:00:00', '上海市', 0, '上海市总工会创新升级“会了嘛”法治外卖服务，将二维码贴纸发放至新就业形态劳动者高频使用场景，首批发放万份，扫码即可免费享受法律咨询、文书代拟、协商调解、仲裁诉讼代理等服务。', 'PUBLISHED', 'EXTERNAL', 'https://www.workercn.cn/c/2025-04-16/8502221.shtml', '310100', '上海市总工会', '法律援助', '上海市总工会创新升级“会了嘛”法治外卖服务，将二维码贴纸发放至新就业形态劳动者高频使用场景，首批发放万份，扫码即可免费享受法律咨询、文书代拟、协商调解、仲裁诉讼代理等服务。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('“法援惠民生·服务新业态”崇明区法律援助中心举办政府开放日暨新业态劳动者权益保障专题活动', NULL, '2025-08-29 00:00:00', '上海市崇明区公共法律服务中心', 0, '崇明区法律援助中心举办政府开放日暨新业态劳动者权益保障专题活动，以外卖骑手为主的新业态劳动者代表参观公共法律服务中心，听取新业态劳动者权益保障专题法律维权讲座并观看普法短视频。', 'PUBLISHED', 'EXTERNAL', 'https://www.shanghai.gov.cn/cmq/20250829/1b19542867a04b20aa4d8f9a9ebb8c28.html', '310100', '上海市崇明区法律援助中心', '法律援助', '崇明区法律援助中心举办政府开放日暨新业态劳动者权益保障专题活动，以外卖骑手为主的新业态劳动者代表参观公共法律服务中心，听取新业态劳动者权益保障专题法律维权讲座并观看普法短视频。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('新业态新就业群体子女如何过暑假？金山朱泾开设了专属爱心暑托班', NULL, '2025-07-07 00:00:00', '上海市金山区朱泾镇（朱泾小学、朱泾二小）', 0, '金山区朱泾镇专为快递小哥、外卖骑手等新业态新就业群体子女开设“爱心暑托班”开班，招收15名学生，提供为期4周的免费托管服务，课程涵盖作业辅导、AI应用、创意美术、乐高搭建等。', 'PUBLISHED', 'EXTERNAL', 'https://www.jfdaily.com/wx/detail.do?id=942160', '310100', '上海市金山区朱泾镇', '子女关爱', '金山区朱泾镇专为快递小哥、外卖骑手等新业态新就业群体子女开设“爱心暑托班”开班，招收15名学生，提供为期4周的免费托管服务，课程涵盖作业辅导、AI应用、创意美术、乐高搭建等。', 'MEDIA');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('“普陀城市骑士”亮相全国劳务品牌成果展', NULL, '2025-11-18 00:00:00', '南宁国际会展中心（第三届全国劳务协作暨劳务品牌发展大会）', 0, '普陀区人社局联合淘宝闪购-饿了么打造的“普陀城市骑士”劳务品牌亮相全国劳务品牌成果展，该品牌在普陀区开设城市骑士网约配送员岗位培训班累计64期、参训学员1350人，并举办市、区级网约配送员职业技能竞赛。', 'PUBLISHED', 'EXTERNAL', 'https://www.shanghai.gov.cn/nw15343/20251121/ed99eb17e115480391d54d3368c598dc.html', '310100', '上海市普陀区人力资源和社会保障局、淘宝闪购-饿了么', '技能培训', '普陀区人社局联合淘宝闪购-饿了么打造的“普陀城市骑士”劳务品牌亮相全国劳务品牌成果展，该品牌在普陀区开设城市骑士网约配送员岗位培训班累计64期、参训学员1350人，并举办市、区级网约配送员职业技能竞赛。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('让追光人在杭州奔涌成浪 浙江杭州工会“新”光成长营全域启航', NULL, '2025-10-27 00:00:00', '圆通速递亚运物流中心（杭州市）', 0, '杭州工会“新”光成长营共建启动活动在圆通速递亚运物流中心举办，标志“新”光成长营全域启航，全市13个区县（市）总工会将打造分营，为新就业形态劳动者提供文化知识赋能与成长礼包。', 'PUBLISHED', 'EXTERNAL', 'https://www.workercn.cn/c/2025-10-28/8641990.shtml', '330100', '杭州市总工会', '技能培训', '杭州工会“新”光成长营共建启动活动在圆通速递亚运物流中心举办，标志“新”光成长营全域启航，全市13个区县（市）总工会将打造分营，为新就业形态劳动者提供文化知识赋能与成长礼包。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('市总工会真诚服务赢得职工赞誉', NULL, '2025-12-31 00:00:00', '杭州市', 0, '杭州市总工会通过送检上门和到体检中心集中体检两种形式，为5700余人次新就业形态劳动者提供免费健康体检，并投入300万元开展“爱心餐”活动、为1000名新就业形态女性劳动者提供免费“两癌”筛查。', 'PUBLISHED', 'EXTERNAL', 'https://www.hzgh.org/newsview107120.htm', '330100', '杭州市总工会', '健康关爱', '杭州市总工会通过送检上门和到体检中心集中体检两种形式，为5700余人次新就业形态劳动者提供免费健康体检，并投入300万元开展“爱心餐”活动、为1000名新就业形态女性劳动者提供免费“两癌”筛查。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('西湖区建设新就业群体友好社会推进会暨“小哥学院·工匠杯”快递员职业技能竞赛开幕式举行', NULL, '2025-08-26 00:00:00', '杭州市西湖区', 0, '2025年西湖区建设新就业群体友好社会推进会暨“小哥学院·工匠杯”快递员职业技能竞赛开幕式举行，会上发布西湖区建设新就业群体友好社会十大标志性成果、新就业群体诉求服务中心，并举行“小哥学院”毕业典礼暨新生入学仪式。', 'PUBLISHED', 'EXTERNAL', 'http://www.hzxh.gov.cn/col/col1177934/art/2025/art_517b9edd9981403d9787736a0707d0fb.html', '330100', '杭州市西湖区（西湖区委、区政府）', '技能培训', '2025年西湖区建设新就业群体友好社会推进会暨“小哥学院·工匠杯”快递员职业技能竞赛开幕式举行，会上发布西湖区建设新就业群体友好社会十大标志性成果、新就业群体诉求服务中心，并举行“小哥学院”毕业典礼暨新生入学仪式。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('崇德向善① | 望江首创“小哥圆桌会”，解决外卖员的“急难愁盼”', NULL, '2025-11-10 00:00:00', '杭州市上城区望江街道近江东园邻里食堂', 0, '望江街道“小哥圆桌会”召开最新一期，议题聚焦新就业形态劳动者权益保障，外卖小哥与街道及区人力社保局工作人员面对面沟通参保、居住证等诉求；该圆桌会自2024年8月起每月召开一次，已举办15场。', 'PUBLISHED', 'EXTERNAL', 'https://apiv4.cst123.cn/cst/news/shareDetail?id=1178627064996036608', '330100', '杭州市上城区文明办、上城区望江街道（“清林公益中心”牵头）', '权益保障', '望江街道“小哥圆桌会”召开最新一期，议题聚焦新就业形态劳动者权益保障，外卖小哥与街道及区人力社保局工作人员面对面沟通参保、居住证等诉求；该圆桌会自2024年8月起每月召开一次，已举办15场。', 'MEDIA');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('2025致敬劳动者 情暖新业态 | 广州市总工会慰问海珠区新业态劳动者', NULL, '2025-04-30 00:00:00', '广州市海珠区凤阳街道户外劳动者工会爱心驿站万达广场站、顺丰速运康乐分部', 0, '广州市总工会副主席带队到海珠区凤阳街道户外劳动者工会爱心驿站万达广场站和顺丰速运康乐分部，慰问网约送餐员和快递员并送上清凉礼包，了解其接单送单情况并建议站点改善工作环境。', 'PUBLISHED', 'EXTERNAL', 'https://www.gzgh.org.cn/article?id=29885', '440100', '广州市总工会、海珠区总工会', '健康关爱', '广州市总工会副主席带队到海珠区凤阳街道户外劳动者工会爱心驿站万达广场站和顺丰速运康乐分部，慰问网约送餐员和快递员并送上清凉礼包，了解其接单送单情况并建议站点改善工作环境。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('全省百余名网约配送精英技能“大比武”', NULL, '2025-12-06 00:00:00', '广州市海珠区同创汇', 0, '2025年广东省网约配送员职业技能竞赛在广州市海珠区同创汇收官，来自全省11个地市的百余名骑手采用“理论+实操”双维度考核同台竞技，共评选出50个个人奖项及14个组织奖项。', 'PUBLISHED', 'EXTERNAL', 'https://www.gdftu.org.cn/ghyw/ldjs/content/post_1313380.html', '440100', '广东省总工会、广东省人力资源和社会保障厅、广东省工业和信息化厅、广东省科学技术厅', '技能培训', '2025年广东省网约配送员职业技能竞赛在广州市海珠区同创汇收官，来自全省11个地市的百余名骑手采用“理论+实操”双维度考核同台竞技，共评选出50个个人奖项及14个组织奖项。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('广州海珠集体协商为快递小哥“代言”', NULL, '2025-09-29 00:00:00', '广州市海珠会议中心', 0, '2025年海珠区第二届“海谐杯”集体协商竞赛总决赛举行，4支晋级队伍分别代表“职工方”和“企业方”，围绕快递行业计件工资调整、强制休息等劳动权益核心议题展开集体协商。', 'PUBLISHED', 'EXTERNAL', 'https://epaper.nfgb.cn/html/2025-10/01/content_16_36875.htm', '440100', '广州市海珠区总工会、海珠区人力资源和社会保障局、海珠区工商业联合会', '权益保障', '2025年海珠区第二届“海谐杯”集体协商竞赛总决赛举行，4支晋级队伍分别代表“职工方”和“企业方”，围绕快递行业计件工资调整、强制休息等劳动权益核心议题展开集体协商。', 'MEDIA');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('为网约配送员送上“健康礼包”，免费体检活动顺利开展', NULL, '2025-11-18 00:00:00', '广州市员村宫户外劳动者爱心驿站', 0, '2025年新就业形态劳动者免费上门体检心检活动在员村宫户外劳动者爱心驿站举办，为网约配送员提供肝功六项、肾功三项、彩超、胸片等多项体检服务，并现场提供暖心早餐。', 'PUBLISHED', 'EXTERNAL', 'https://news.dayoo.com/guangzhou/202511/18/139995_54895708.htm', '440100', '广州市总工会（指导）、广州市网约配送行业工会联合会、广州市员村工人文化宫、广州市工人疗养院', '健康关爱', '2025年新就业形态劳动者免费上门体检心检活动在员村宫户外劳动者爱心驿站举办，为网约配送员提供肝功六项、肾功三项、彩超、胸片等多项体检服务，并现场提供暖心早餐。', 'MEDIA');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('龙岗区启动2025年新就业形态劳动者服务月', NULL, '2025-05-09 00:00:00', '深圳市龙岗区天安数码城园区广场', 0, '龙岗区总工会2025年新就业形态劳动者服务月暨第二届技能竞赛启动，发布涵盖思想引领、权益维护、技能提升、生活关爱、文化融入及组织建设六大领域共233场活动，并同步启动第二届新就业形态劳动者技能竞赛。', 'PUBLISHED', 'EXTERNAL', 'http://sz-qb.com/PC/content/202505/14/content_77356.html', '440300', '深圳市龙岗区总工会', '技能培训', '龙岗区总工会2025年新就业形态劳动者服务月暨第二届技能竞赛启动，发布涵盖思想引领、权益维护、技能提升、生活关爱、文化融入及组织建设六大领域共233场活动，并同步启动第二届新就业形态劳动者技能竞赛。', 'MEDIA');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('深圳龙华聚焦骑手实际需求推出创新服务', NULL, '2025-08-08 00:00:00', '深圳市龙华区', 0, '龙华区举行“骑士节”暨美团骑手党建及服务管理总结交流活动，新成立4个骑手党支部、10名骑手获评“最美新业态劳动者”，发布“骑士节专属关怀清单”提供12类百余项服务，并发放5000份防暑礼包、增设30个“爱心冰柜”补给点。', 'PUBLISHED', 'EXTERNAL', 'https://www.gdftu.org.cn/xwzx/jcld/content/post_1301004.html', '440300', '深圳市委社会工作部、市委互联网企业工委、美团（深圳）党委、龙华区委社会工作部、龙华区委宣传部、龙华区总工会', '权益保障', '龙华区举行“骑士节”暨美团骑手党建及服务管理总结交流活动，新成立4个骑手党支部、10名骑手获评“最美新业态劳动者”，发布“骑士节专属关怀清单”提供12类百余项服务，并发放5000份防暑礼包、增设30个“爱心冰柜”补给点。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('龙华新石社区工联会举办新业态群体劳动技能竞赛', NULL, '2025-09-18 00:00:00', '深圳市龙华区大浪街道新石社区浩盛隆营业店', 0, '新业态群体劳动技能竞赛在深圳龙华区大浪街道新石社区举行，来自辖区的10支队伍共50名快递员参加情景演练、心肺复苏急救演练和打包技能比赛三个项目，以赛代训提升从业技能。', 'PUBLISHED', 'EXTERNAL', 'https://m.mp.oeeee.com/a/BAAFRD0000202509171124256.html', '440300', '深圳市龙华区大浪街道总工会、深圳市龙华区新就业形态行业工会联合会（指导），深圳市龙华区大浪街道新石社区工会联合会', '技能培训', '新业态群体劳动技能竞赛在深圳龙华区大浪街道新石社区举行，来自辖区的10支队伍共50名快递员参加情景演练、心肺复苏急救演练和打包技能比赛三个项目，以赛代训提升从业技能。', 'MEDIA');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('盐田区梅沙街道大梅沙社区开展“暖骑同行，社区相伴”新就业群体暖心慰问活动', NULL, '2025-09-29 00:00:00', '深圳市盐田区大梅沙社区榕合之家“小个专党建阵地”', 0, '大梅沙社区党委开展“暖骑同行，社区相伴”活动，邀请梅沙社康中心医生为顺丰、京东、美团等10余名骑手讲解意外摔伤应急处置方法，发放倡议书及挂脖小风扇、充电宝、冰袖等暖心礼包并听取诉求。', 'PUBLISHED', 'EXTERNAL', 'https://www.sz.gov.cn/cn/xxgk/zfxxgj/gqdt/content/post_12418375.html', '440300', '深圳市盐田区梅沙街道大梅沙社区党委', '健康关爱', '大梅沙社区党委开展“暖骑同行，社区相伴”活动，邀请梅沙社康中心医生为顺丰、京东、美团等10余名骑手讲解意外摔伤应急处置方法，发放倡议书及挂脖小风扇、充电宝、冰袖等暖心礼包并听取诉求。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('龙岗街道“代表+工会”携手开展新就业形态劳动者子女英语阅读体验课活动', NULL, '2025-11-20 00:00:00', '深圳市龙岗区龙岗街道党群服务中心人大代表会议室', 0, '龙岗街道总工会联合人大等举办新就业形态劳动者子女英语阅读体验课活动，为辖区外卖员、快递员等新业态劳动者子女提供英语字母拼读、趣味歌谣、日常口语练习并赠送文具礼包。', 'PUBLISHED', 'EXTERNAL', 'https://www.lg.gov.cn/bmzz/lgjdb/xxgk/qt/jcrd/rdjj/content/post_12506050.html', '440300', '深圳市龙岗区龙岗街道总工会、党政和人大办（人大）、深圳市龙岗区金翅膀教育中心', '子女关爱', '龙岗街道总工会联合人大等举办新就业形态劳动者子女英语阅读体验课活动，为辖区外卖员、快递员等新业态劳动者子女提供英语字母拼读、趣味歌谣、日常口语练习并赠送文具礼包。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('骑士关怀日暨武汉爱心餐活动启动', NULL, '2025-07-17 00:00:00', '武汉市武昌区都府堤社区区域性职工之家', 0, '717骑士关怀日暨武汉爱心餐“餐餐有爱 免单e夏”活动启动，为外卖员、快递员、网约车司机等新就业群体行业代表驿站送去爱心餐免单文创包和清凉物资，现场设“骑士关怀福利集市”提供免费义剪、按摩、心理咨询并发放200份清凉礼包。', 'PUBLISHED', 'EXTERNAL', 'https://www.workercn.cn/c/2025-07-20/8565669.shtml', '420100', '湖北省总工会、武汉市总工会（指导），武昌区总工会、武汉饿了么蓝骑士工会联合会', '健康关爱', '717骑士关怀日暨武汉爱心餐“餐餐有爱 免单e夏”活动启动，为外卖员、快递员、网约车司机等新就业群体行业代表驿站送去爱心餐免单文创包和清凉物资，现场设“骑士关怀福利集市”提供免费义剪、按摩、心理咨询并发放200份清凉礼包。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('走马岭街举行新业态领域人才劳动技能竞赛', NULL, '2024-09-19 00:00:00', '武汉市东西湖区走马岭街', 0, '走马岭街首届新业态领域人才劳动技能竞赛举行，吸引顺丰、中通、安能、双汇等企业近百名技能人才同台竞技，现场比拼分为团队展示、安全演练和驾驶实操三个环节。', 'PUBLISHED', 'EXTERNAL', 'https://m-cjyun.dxhrmt.cn/p/15712.html', '420100', '武汉市东西湖区走马岭街道办事处、东西湖区总工会', '技能培训', '走马岭街首届新业态领域人才劳动技能竞赛举行，吸引顺丰、中通、安能、双汇等企业近百名技能人才同台竞技，现场比拼分为团队展示、安全演练和驾驶实操三个环节。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('便民服务暖“新”心 法治护航伴前行 江夏区司法局开展新就业群体便民法律服务', NULL, '2025-11-11 00:00:00', '武汉市江夏区纸坊街龙井社区“4号户外工作者驿站”', 0, '江夏区司法局联合龙井社区在“4号户外工作者驿站”开展服务新就业群体便民法律服务活动，设置便民咨询台，普及劳动合同签订、欠薪维权、交通事故处理、工伤保险等高频法律知识并提供一对一答疑，提供法律咨询20余人次、发放资料300余份。', 'PUBLISHED', 'EXTERNAL', 'http://hbwh.wenming.cn/oldweb/jx/202511/t20251118_9080829.html', '420100', '武汉市江夏区司法局公共法律服务管理科、纸坊街龙井社区', '法律援助', '江夏区司法局联合龙井社区在“4号户外工作者驿站”开展服务新就业群体便民法律服务活动，设置便民咨询台，普及劳动合同签订、欠薪维权、交通事故处理、工伤保险等高频法律知识并提供一对一答疑，提供法律咨询20余人次、发放资料300余份。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('他们有绝活！江汉区2名选手入围全市决赛', NULL, '2024-11-07 00:00:00', '武汉市江汉区', 0, '武汉市“工友杯”第二届“武有绝活”高技能人才技能大赛初赛结束，江汉区外卖小哥张宝剑在现代服务及新就业形态类中脱颖而出，成功晋级决赛。', 'PUBLISHED', 'EXTERNAL', 'https://www.jianghan.gov.cn/qt/qzgh/ghdt/202411/t20241119_2486527.shtml', '420100', '武汉市总工会、武汉市人力资源和社会保障局（主办），江汉区总工会', '技能培训', '武汉市“工友杯”第二届“武有绝活”高技能人才技能大赛初赛结束，江汉区外卖小哥张宝剑在现代服务及新就业形态类中脱颖而出，成功晋级决赛。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('2025年成都市“爱心冰柜”公益活动正式启动', NULL, '2025-08-05 00:00:00', '成都市锦江区总工会书院工会驿站', 0, '2025年成都市“爱心冰柜”公益活动启动，依托成都市工会驿站设立首批681个“爱心冰柜”点位，投放20万瓶矿泉水，为环卫工、快递员、外卖骑手、网约车司机等户外工作者提供免费清凉饮品。', 'PUBLISHED', 'EXTERNAL', 'http://sc.people.com.cn/BIG5/n2/2025/0806/c379469-41314550.html', '510100', '四川省总工会、四川省慈善联合总会（指导），川观新闻、成都市总工会', '健康关爱', '2025年成都市“爱心冰柜”公益活动启动，依托成都市工会驿站设立首批681个“爱心冰柜”点位，投放20万瓶矿泉水，为环卫工、快递员、外卖骑手、网约车司机等户外工作者提供免费清凉饮品。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('2025年成都百万职工技能大赛高新区快递员技能比赛成功举行', NULL, '2025-09-25 00:00:00', '成都高新区24H肖+青年职工之家', 0, '2025年成都百万职工技能大赛高新区快递员技能比赛举行，来自中国邮政、中通物流、顺丰速运、德邦物流等30名快递员参赛，理论考试围绕行业标准、职业道德、职业安全展开，实操设置“闪电分拣战”和“智慧路线战”环节。', 'PUBLISHED', 'EXTERNAL', 'https://www.cdht.gov.cn/cdht/c139674/2025-09/26/content_5f61ffc38ad141b088e3df0312ab3bd5.shtml', '510100', '成都高新区总工会（主办），成都高新区肖家河街道总工会（承办）', '技能培训', '2025年成都百万职工技能大赛高新区快递员技能比赛举行，来自中国邮政、中通物流、顺丰速运、德邦物流等30名快递员参赛，理论考试围绕行业标准、职业道德、职业安全展开，实操设置“闪电分拣战”和“智慧路线战”环节。', 'GOV');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('成都市锦江区柳江街道总工会开展关爱新就业形态劳动者送清凉活动', NULL, '2025-07-23 00:00:00', '成都市德必川报易园工会驿站、锦江区总工会工会驿站', 0, '柳江街道总工会依托辖区工会驿站开展“清凉沁‘新’ 暖新同行”关爱新就业形态劳动者送清凉系列活动，7月23日至25日提供发型修剪、中医把脉、血压测量及防暑清凉包领取，惠及百余名快递员、外卖员、环卫工人。', 'PUBLISHED', 'EXTERNAL', 'https://www.51grb.cn/ghnew2024/content_49856', '510100', '成都市锦江区柳江街道总工会（锦江区总工会指导）', '健康关爱', '柳江街道总工会依托辖区工会驿站开展“清凉沁‘新’ 暖新同行”关爱新就业形态劳动者送清凉系列活动，7月23日至25日提供发型修剪、中医把脉、血压测量及防暑清凉包领取，惠及百余名快递员、外卖员、环卫工人。', 'MEDIA');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('以心暖“新” 锦江区成龙路街道为新就业群体送上冬日关怀', NULL, '2025-12-30 00:00:00', '成都市锦江区成龙路街道R29工会驿站', 0, '成龙路街道举办“暖冬慰问·情暖小哥”新就业群体服务行动，设健康守护、趣味游园、便民服务、美食体验四大区域，提供血压血糖检测、内科外科问诊、专业按摩、免费手机贴膜及暖冬慰问礼包。', 'PUBLISHED', 'EXTERNAL', 'https://cbgc.scol.com.cn/news/7129941', '510100', '成都市锦江区成龙路街道党工委、办事处、街道总工会（粮丰社区、成龙路社区卫生服务中心协办）', '健康关爱', '成龙路街道举办“暖冬慰问·情暖小哥”新就业群体服务行动，设健康守护、趣味游园、便民服务、美食体验四大区域，提供血压血糖检测、内科外科问诊、专业按摩、免费手机贴膜及暖冬慰问礼包。', 'MEDIA');
INSERT INTO activity (title, station_id, activity_time, address, max_count, content, status, organizer_type, external_url, city_code, publisher, category, summary, source_level) VALUES ('新年get新技能，成都高新区这个街道总工会为百余名新就业形态劳动者暖心赋能', NULL, '2025-12-30 00:00:00', '成都高新区合庆里街区', 0, '成都高新区西园街道总工会举办“元启新程·工会聚暖”新年惠企暖新游园会，约150名新就业形态劳动者参与，六大活动站点中“聚安护航·应急救护培训站”由专业讲师手把手教学心肺复苏、海姆立克急救法及外伤包扎流程。', 'PUBLISHED', 'EXTERNAL', 'https://cbgc.scol.com.cn/news/7125543', '510100', '成都高新区西园街道总工会', '技能培训', '成都高新区西园街道总工会举办“元启新程·工会聚暖”新年惠企暖新游园会，约150名新就业形态劳动者参与，六大活动站点中“聚安护航·应急救护培训站”由专业讲师手把手教学心肺复苏、海姆立克急救法及外伤包扎流程。', 'MEDIA');
